contracts/EventAggregator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IGradientMarketMakerFactory} from "./interfaces/IGradientMarketMakerFactory.sol";

/**
 * @title EventAggregator
 * @notice Centralized event emission for all Gradient pools
 */
contract EventAggregator is Ownable {
    // Factory address to verify pool calls
    address public factory;

    // Event types
    uint8 public constant ETH_ADD = 0;
    uint8 public constant ETH_REMOVE = 1;
    uint8 public constant TOKEN_ADD = 2;
    uint8 public constant TOKEN_REMOVE = 3;
    uint8 public constant ETH_REWARDS_CLAIMED = 4;
    uint8 public constant TOKEN_REWARDS_CLAIMED = 5;
    uint8 public constant TRADE_EXECUTED = 6;

    // Main liquidity event - emitted for all pool operations
    event LiquidityEvent(
        address indexed pool,
        address indexed user,
        address indexed token,
        uint8 eventType,
        uint256 amount,
        uint256 minPrice,
        uint256 maxPrice,
        uint256 timestamp
    );

    // Pool creation event
    event PoolCreated(
        address indexed token,
        address indexed pool,
        uint256 timestamp
    );

    // Trade execution event
    event TradeExecuted(
        address indexed pool,
        address indexed user,
        uint8 tradeType, // 0=BUY, 1=SELL
        uint256 ethAmount,
        uint256 tokenAmount,
        uint256 timestamp
    );

    // Merkle root update event
    event MerkleRootUpdated(
        address indexed pool,
        uint256 indexed version,
        bytes32 merkleRoot,
        uint256 timestamp
    );

    // Factory update event
    event FactoryUpdated(
        address indexed oldFactory,
        address indexed newFactory
    );

    // Constructor
    constructor(address _factory) Ownable(msg.sender) {
        require(_factory != address(0), "Invalid factory address");
        factory = _factory;
    }

    // Modifiers
    modifier onlyPool() {
        require(
            IGradientMarketMakerFactory(factory).isValidPool(msg.sender),
            "Not a valid pool"
        );
        _;
    }

    modifier onlyFactory() {
        require(msg.sender == factory, "Only factory can call");
        _;
    }

    // =============================== LIQUIDITY EVENTS ===============================

    /**
     * @notice Emit liquidity event (called by pools)
     * @param user User address
     * @param token Token address
     * @param eventType Type of liquidity event
     * @param amount Amount involved
     */
    function emitLiquidityEvent(
        address user,
        address token,
        uint8 eventType,
        uint256 amount,
        uint256 minPrice,
        uint256 maxPrice
    ) external onlyPool {
        require(eventType <= TOKEN_REWARDS_CLAIMED, "Invalid event type");
        require(user != address(0), "Invalid user address");
        require(token != address(0), "Invalid token address");

        emit LiquidityEvent(
            msg.sender, // pool address
            user,
            token,
            eventType,
            amount,
            minPrice,
            maxPrice,
            block.timestamp
        );
    }

    /**
     * @notice Emit ETH rewards claimed event
     * @param user User address
     * @param token Token address
     * @param amount Amount of ETH rewards claimed
     */
    function emitETHRewardsClaimed(
        address user,
        address token,
        uint256 amount
    ) external onlyPool {
        require(user != address(0), "Invalid user address");
        require(token != address(0), "Invalid token address");

        emit LiquidityEvent(
            msg.sender, // pool address
            user,
            token,
            ETH_REWARDS_CLAIMED,
            amount,
            0, // minPrice - rewards don't have price ranges
            0, // maxPrice - rewards don't have price ranges
            block.timestamp
        );
    }

    /**
     * @notice Emit token provider rewards claimed event
     * @param user User address
     * @param token Token address
     * @param amount Amount of token provider rewards claimed
     */
    function emitTokenRewardsClaimed(
        address user,
        address token,
        uint256 amount
    ) external onlyPool {
        require(user != address(0), "Invalid user address");
        require(token != address(0), "Invalid token address");

        emit LiquidityEvent(
            msg.sender, // pool address
            user,
            token,
            TOKEN_REWARDS_CLAIMED,
            amount,
            0, // minPrice - rewards don't have price ranges
            0, // maxPrice - rewards don't have price ranges
            block.timestamp
        );
    }

    // =============================== TRADE EVENTS ===============================

    /**
     * @notice Emit trade execution event
     * @param user User address (orderbook)
     * @param tradeType Type of trade (0=BUY, 1=SELL)
     * @param ethAmount ETH amount involved
     * @param tokenAmount Token amount involved
     */
    function emitTradeExecuted(
        address user,
        uint8 tradeType,
        uint256 ethAmount,
        uint256 tokenAmount
    ) external onlyPool {
        require(tradeType <= 1, "Invalid trade type");
        require(user != address(0), "Invalid user address");

        emit TradeExecuted(
            msg.sender, // pool address
            user,
            tradeType,
            ethAmount,
            tokenAmount,
            block.timestamp
        );
    }

    // =============================== MERKLE ROOT EVENTS ===============================

    /**
     * @notice Emit merkle root update event
     * @param version New version number
     * @param merkleRoot New merkle root
     */
    function emitMerkleRootUpdated(
        uint256 version,
        bytes32 merkleRoot
    ) external onlyPool {
        require(merkleRoot != bytes32(0), "Invalid merkle root");

        emit MerkleRootUpdated(
            msg.sender, // pool address
            version,
            merkleRoot,
            block.timestamp
        );
    }

    // =============================== POOL CREATION EVENTS ===============================

    /**
     * @notice Emit pool creation event (called by factory)
     * @param token Token address
     * @param pool Pool address
     */
    function emitPoolCreated(address token, address pool) external onlyFactory {
        require(token != address(0), "Invalid token address");
        require(pool != address(0), "Invalid pool address");

        emit PoolCreated(token, pool, block.timestamp);
    }

    // =============================== ADMIN FUNCTIONS ===============================

    /**
     * @notice Set the factory address (only owner)
     * @param _factory New factory address
     * @dev Allows updating the factory when a new factory is deployed
     */
    function setFactory(address _factory) external onlyOwner {
        require(_factory != address(0), "Invalid factory address");
        require(_factory.code.length > 0, "Factory must be a contract");

        address oldFactory = factory;
        factory = _factory;

        emit FactoryUpdated(oldFactory, _factory);
    }

    // =============================== VIEW FUNCTIONS ===============================

    /**
     * @notice Get event type name for human readability
     * @param eventType Event type number
     * @return name Human readable event type name
     */
    function getEventTypeName(
        uint8 eventType
    ) external pure returns (string memory name) {
        if (eventType == ETH_ADD) return "ETH_ADD";
        if (eventType == ETH_REMOVE) return "ETH_REMOVE";
        if (eventType == TOKEN_ADD) return "TOKEN_ADD";
        if (eventType == TOKEN_REMOVE) return "TOKEN_REMOVE";
        if (eventType == ETH_REWARDS_CLAIMED) return "ETH_REWARDS_CLAIMED";
        if (eventType == TOKEN_REWARDS_CLAIMED) return "TOKEN_REWARDS_CLAIMED";
        if (eventType == TRADE_EXECUTED) return "TRADE_EXECUTED";
        return "UNKNOWN";
    }

    /**
     * @notice Get trade type name for human readability
     * @param tradeType Trade type number
     * @return name Human readable trade type name
     */
    function getTradeTypeName(
        uint8 tradeType
    ) external pure returns (string memory name) {
        if (tradeType == 0) return "BUY";
        if (tradeType == 1) return "SELL";
        return "UNKNOWN";
    }
}

contracts/interfaces/IGradientMarketMake.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IGradientMarketMakerFactory {
    // Events
    event PoolCreated(
        address indexed token,
        address indexed pool,
        uint256 timestamp
    );

    // Pool management
    function createPool(address token) external returns (address pool);

    function createPoolWithLiquidity(
        address token,
        address initialLiquidityProvider,
        uint256 initialEthAmount,
        uint256 initialTokenAmount
    ) external payable returns (address pool);

    function getPool(address token) external view returns (address pool);

    function poolExists(address token) external view returns (bool);

    function getAllPools() external view returns (address[] memory);

    function getPoolCount() external view returns (uint256);

    // Pool info
    function pools(uint256 index) external view returns (address);

    function poolCount() external view returns (uint256);

    // Factory info
    function owner() external view returns (address);

    function getEventAggregator() external view returns (address);

    function setEventAggregator(address _eventAggregator) external;

    /**
     * @notice Get the registry address
     * @return registryAddress Address of the GradientRegistry
     */
    function getRegistry() external view returns (address);

    /**
     * @notice Check if a given address is a valid pool
     * @param poolAddress Address to check
     * @return isValid True if the address is a valid pool
     */
    function isValidPool(
        address poolAddress
    ) external view returns (bool isValid);
}

